import {resolveCostModel} from './costs.js?v=preview-v11';
export function assetClassFor(data){if(data?.assetClass!==undefined){if(['etf','stock'].includes(data.assetClass))return data.assetClass;throw Error('歷史資料商品類型不支援');}if(data?.instrument==='0050 元大台灣50')return 'etf';throw Error('歷史資料缺少可驗證的商品類型，無法設定交易成本');}
export function seededIndex(seed,size){let h=2166136261;for(const c of String(seed)){h^=c.codePointAt(0);h=Math.imul(h,16777619);}return (h>>>0)%size;}
export function eligibleStarts(data,length=20,warmup=40,startYear='all'){if(!Number.isInteger(length)||length<1)throw Error('回合長度必須是正整數');return data.bars.slice(warmup,data.bars.length-length).filter((b,i)=>{if(startYear!=='all'&&!b.date.startsWith(String(startYear)+'-'))return false;const first=data.bars[i].date,last=data.bars[i+warmup+length].date;return !(data.replayCoverage?.unexplainedGaps??[]).some(g=>g.start<=last&&g.end>=first);}).map(b=>b.date);}
export function randomSeed(){return Array.from(crypto.getRandomValues(new Uint32Array(2)),x=>x.toString(36)).join('-');}
export function createScenario(data,{seed=null,length=20,startDate=null,warmup=40,startYear='all',excludeStart=null,costModel}={}){const assetClass=assetClassFor(data),costs=resolveCostModel(costModel,assetClass);let eligible=eligibleStarts(data,length,warmup,startYear);if(!eligible.length)throw Error('該範圍沒有足夠暖機與完整回合');const random=seed==null&&!startDate;seed=seed??randomSeed();if(random&&eligible.length>1&&excludeStart){const base=seed;let attempt=0;while(eligible[seededIndex(seed,eligible.length)]===excludeStart){seed=base+'-reroll-'+(++attempt);}}const chosen=startDate??eligible[seededIndex(seed,eligible.length)];if(!eligible.includes(chosen))throw Error('開始日期沒有足夠前後資料，或不在所選年份');const start=data.bars.findIndex(b=>b.date===chosen);const actions=data.corporateActions??[];const splitFor=date=>actions.filter(a=>a.type==='split'&&(a.effectiveDate??a.exDate)===date).reduce((f,a)=>f*a.ratio,1);const actionNews=actions.filter(a=>a.announcementDate&&a.announcementDisplayEligible!==false).map(a=>({id:a.type+'-'+(a.exDate??a.effectiveDate),publishedAt:a.publishedAt??a.publicationTimestamp??null,availableAt:a.availableAt??a.publishedAt??a.publicationTimestamp??new Date(a.announcementDate+'T16:00:00Z').toISOString(),timestampPrecision:(a.publishedAt??a.publicationTimestamp)?'second':'date_only',title:a.type==='split'?`0050 分割恢復交易／參考價公告：1 單位分為 ${a.ratio} 單位`:`0050 收益分配公告：每單位 ${a.cashPerUnit} 元`,body:a.type==='split'?`公告日期 ${a.announcementDate}，${(a.publishedAt??a.publicationTimestamp)?'保留原始發布時間。':'精確發布時間未驗證；保守於次日顯示。'}分割生效交易日 ${a.effectiveDate??a.exDate}。${a.earlierScheduleAnnouncementDate?`本公告為最終單位與參考價公告，並非首次公告；較早時程公告日期 ${a.earlierScheduleAnnouncementDate} 的原頁未完成驗證。`:""}`:`公告日期 ${a.announcementDate}，${(a.publishedAt??a.publicationTimestamp)?'保留原始發布時間。':'精確發布時間未驗證；保守於次日顯示。'}除息日 ${a.exDate}，發放日 ${a.paymentDate}。`,source:a.source,url:a.url}));return {datasetLabel:data.replayDataset?.label??null,dataCoverage:data.replayCoverage??null,id:`0050-${data.bars[0].date}-${data.bars.at(-1).date}-${data.bars.length}-${chosen}-${length}-${seed}`,seed,startDate:chosen,requestedStartDate:startDate,startYear,warmup,length,random,title:'0050 真實歷史 K 線回放',asset:data.instrument,currency:data.currency,initialCash:100000,assetClass,feeRate:costs.feeRate,costModel:costs,kind:'historical',history:data.bars.slice(start-warmup,start),news:[...(data.events??[]),...actionNews],corporateActions:actions,sources:data.sources??[],description:`${data.bars[0].date}–${data.bars.at(-1).date} 歷史庫 · ${length} 個決策日 · ${warmup} 個練習前交易日 · 起點 ${chosen}`,rounds:data.bars.slice(start,start+length).map((bar,i)=>{const prior=data.bars[start+i-1],next=data.bars[start+i+1],splitRatio=splitFor(bar.date);return {at:bar.date+'T00:55:00Z',price:prior.close/splitRatio,priceAt:prior.closeAt,splitRatio,executionAt:bar.openAt,executionPrice:bar.open,closeAt:bar.closeAt,close:bar.close,revealAt:next.date+'T00:55:00Z',bar,news:[]};})};}
export function indicators(bars){const closes=bars.map(b=>b.close),last=bars.at(-1),prior=bars.at(-2);const sma=n=>closes.length<n?null:closes.slice(-n).reduce((a,b)=>a+b,0)/n;const returns=closes.slice(-21).slice(1).map((p,i)=>Math.log(p/closes.slice(-21)[i]));let vol=null;if(returns.length===20){const mean=returns.reduce((a,b)=>a+b,0)/20;vol=Math.sqrt(returns.reduce((a,b)=>a+(b-mean)**2,0)/19)*Math.sqrt(252)*100;}const meanVolume=bars.length>=20?bars.slice(-20).reduce((a,b)=>a+(b.comparableVolume??b.volume),0)/20:null;return {sma5:sma(5),sma20:sma(20),change:prior?(last.close/prior.close-1)*100:null,return20:closes.length>=21?(last.close/closes.at(-21)-1)*100:null,volatility20:vol,meanVolume,volumeRatio:meanVolume?(last.comparableVolume??last.volume)/meanVolume:null,high20:bars.length>=20?Math.max(...bars.slice(-20).map(x=>x.high)):null,low20:bars.length>=20?Math.min(...bars.slice(-20).map(x=>x.low)):null};}
